head.script:
		
		
	    	var objParent = opener || parent;
	        var callBackFunc = WebSquare.net.getParameter( "fname" );
    
		   /**************************************************************************
	        * function    : init
	        * Description : 화면 로드시 실행 됨.
	        * Parameter   : null
	        * Return      : null
	        **************************************************************************/
	        function init() {
	        	var selectedItem = getCookie("bisFavorMenuList");
	        	if(selectedItem!=null || selectedItem!="") {
	        		var selectedList = selectedItem.split("|");
	        		Bookcheckbox1.setValue( selectedList.join(" "));
	        	}
	        	attachEventTD();
	        }    	
	       
	       /**************************************************************************
	        * function    : closeWindow()
	        * Description : 선택 자료를 return 하고 창 당기
	        * Parameter   : null
	        * Return      : null
	        **************************************************************************/ 
	        function closeWindow() {
				var retVal = Bookcheckbox1.getValue("|");
				objParent.eval(callBackFunc)(retVal,"npop2");
	        }
	        
	       /**************************************************************************
	        * function    : attachEventTD
	        * Description : TD영역에 클릭 이벤트 설정
	        * Parameter   : null
	        * Return      : null
	        **************************************************************************/ 
	        function attachEventTD() {
	        	for(var i=0 ; i < Bookcheckbox1.getItemCount() ; i++) {
	        		var id="#Bookcheckbox1_input_"+i;
	        		var inputId="#Bookcheckbox1_input_"+i;
	        		var tdObj= $(id).parent();
	        		
	        		tdObj.attr("id",i);
					tdObj.bind("click", function(){
						var isChecked = $("#Bookcheckbox1_input_"+this.id).is(":checked");
						if(getSelectedCount() >= 9 && !isChecked) {
							showMsgString("최대 9개까지 선택할 수 있습니다.");
						} else {
							Bookcheckbox1.setSelectedIndex( this.id );
						} 
					});
					$(inputId).bind("click", function(e){
						var isChecked = $(this).is(":checked");
						if(getSelectedCount() > 9 && isChecked) {
							showMsgString("최대 9개까지 선택할 수 있습니다.");
							e.preventDefault();
						} else {
							e.stopPropagation();
						} 
				    });
	        	}
	        }
	        
	       /**************************************************************************
	        * function    : getSelectedCount
	        * Description : 선택 갯수 구하기
	        * Parameter   : null
	        * Return      : null
	        **************************************************************************/ 
	        function getSelectedCount() {
				var selectedList = Bookcheckbox1.getSelectedIndex("|");
				var count=selectedList.split("|").length;
				return count;
	        }

	        init();
